const size_t N = 100;
int* dyn_arr;

// Allocate block for N integers
dyn_arr = (int*)malloc(N * sizeof(int));

// Check for allocation failure
if (dyn_arr == NULL) { /* Handle error */ }

// Use the dynamically allocated memory
dyn_arr[0] = 42;
*(dyn_arr + 1) = 99;

// Release the memory block
free(dyn_arr);

// Best practice: clear pointer after freeing
dyn_arr = NULL;
